#!/usr/bin/env bash
# Applies מעשרותי's customizations to the Android project generated by `npx cap add android`.
set -euo pipefail

RUN="${GITHUB_RUN_NUMBER:-1}"
VERSION="${APP_VERSION:-1.0}"
APP=android/app
RES=$APP/src/main/res
MAN=$APP/src/main/AndroidManifest.xml

# 1) Icons, notification icon and splash
find "$RES" -name 'splash.png' -delete
cp -R android-res/. "$RES/"

# 2) App name in Hebrew (the label under the icon)
STR=$RES/values/strings.xml
perl -0pi -e 's|<string name="app_name">[^<]*</string>|<string name="app_name">מעשרותי</string>|; s|<string name="title_activity_main">[^<]*</string>|<string name="title_activity_main">מעשרותי</string>|' "$STR"

# 3) Permissions: reminders (weekly and salary days), camera for receipts, network state
perl -0pi -e 's|</manifest>|    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />\n    <uses-permission android:name="android.permission.POST_NOTIFICATIONS" />\n    <uses-permission android:name="android.permission.SCHEDULE_EXACT_ALARM" />\n    <uses-permission android:name="android.permission.RECEIVE_BOOT_COMPLETED" />\n    <uses-permission android:name="android.permission.VIBRATE" />\n    <uses-permission android:name="android.permission.CAMERA" />\n    <uses-feature android:name="android.hardware.camera" android:required="false" />\n</manifest>|' "$MAN"

# 4) Deep-blue splash with the coin on Android 12+
STY=$RES/values/styles.xml
perl -0pi -e 's|(<style name="AppTheme.NoActionBarLaunch" parent="Theme.SplashScreen">)|$1\n        <item name="windowSplashScreenBackground">#173A7A</item>\n        <item name="windowSplashScreenAnimatedIcon">\@mipmap/ic_launcher_foreground</item>|' "$STY"

# 5) Target SDK 34 (classic status bar; the app is installed directly, not from Play)
sed -i -E 's/targetSdkVersion = [0-9]+/targetSdkVersion = 34/' android/variables.gradle

# 6) Version: name is the product version, code is the build number (so every APK installs as an update)
sed -i -E "s/versionCode [0-9]+/versionCode ${RUN}/; s/versionName \"[^\"]*\"/versionName \"${VERSION}\"/" "$APP/build.gradle"

# 7) Release signing with the permanent key (password from GitHub secrets)
cat >> "$APP/build.gradle" <<'GRADLE'

android {
    signingConfigs {
        maasroti {
            storeFile file("release.jks")
            storePassword System.getenv("MAASROTI_STORE_PASSWORD")
            keyAlias System.getenv("MAASROTI_KEY_ALIAS")
            keyPassword System.getenv("MAASROTI_KEY_PASSWORD")
        }
    }
    buildTypes {
        release {
            signingConfig signingConfigs.maasroti
            minifyEnabled false
        }
    }
}
GRADLE

echo "--- manifest"; grep -n 'uses-permission\|uses-feature' "$MAN"
echo "--- strings"; cat "$STR"
echo "--- launch style"; grep -n -A3 'NoActionBarLaunch' "$STY"
echo "--- versions"; grep -n -E 'versionCode|versionName' "$APP/build.gradle"; grep -n targetSdk android/variables.gradle
